// ============================================================
// ProcureGuard AI - Normalize Global Workflow Error
// ============================================================

const input = $input.first().json;

// Error Trigger payload can differ depending on how/where
// the source workflow failed.
const execution = input.execution || {};
const workflow = input.workflow || {};
const trigger = input.trigger || {};

const error =
  execution.error ||
  input.error ||
  {};

const workflowName =
  workflow.name ||
  input.workflowName ||
  "Unknown Workflow";

const workflowId =
  workflow.id ||
  input.workflowId ||
  null;

const executionId =
  execution.id ||
  input.executionId ||
  null;

const executionUrl =
  execution.url ||
  null;

const lastNodeExecuted =
  execution.lastNodeExecuted ||
  input.lastNodeExecuted ||
  null;

const errorMessage =
  error.message ||
  input.message ||
  "Unknown workflow execution error.";

const errorDescription =
  error.description ||
  null;

const errorStack =
  error.stack ||
  null;

// ------------------------------------------------------------
// Classify severity
// ------------------------------------------------------------

const messageForClassification =
  `${errorMessage} ${errorDescription || ""}`.toLowerCase();

const criticalPatterns = [
  "authentication",
  "unauthorized",
  "credential",
  "database",
  "connection refused",
  "connection terminated",
  "timeout",
  "out of memory",
  "permission denied",
];

const isCritical =
  criticalPatterns.some(pattern =>
    messageForClassification.includes(pattern)
  );

const severity =
  isCritical ? "CRITICAL" : "ERROR";

// ------------------------------------------------------------
// Return normalized error
// ------------------------------------------------------------

return [
  {
    json: {
      workflow_name: String(workflowName),

      workflow_id:
        workflowId ? String(workflowId) : null,

      workflow_execution_id:
        executionId ? String(executionId) : null,

      execution_url:
        executionUrl ? String(executionUrl) : null,

      failed_node:
        lastNodeExecuted
          ? String(lastNodeExecuted)
          : null,

      error_message:
        String(errorMessage),

      error_description:
        errorDescription
          ? String(errorDescription)
          : null,

      error_stack:
        errorStack
          ? String(errorStack).slice(0, 10000)
          : null,

      severity,

      requires_alert:
        severity === "CRITICAL",

      source:
        "N8N_GLOBAL_ERROR_HANDLER",

      captured_at:
        new Date().toISOString()
    }
  }
];
